export type RouteId = (typeof ROUTES)[number]['id'];

const BY_ID = new Map(ROUTES.map((r) => [r.id, r]));

/** The route with this id. Throws on an unknown id: the table is the contract. */
export function route(id: RouteId): ApiRoute {
	const r = BY_ID.get(id);
	if (!r) throw new Error(`unknown route id: ${id}`);
	return r;
}

/** Route path with `{param}` placeholders substituted, WITHOUT the api prefix. */
export function path(id: RouteId, params: Record<string, string | number> = {}): string {
	return route(id).path.replace(/\{(\w+)\}/g, (whole, name: string) =>
		name in params ? encodeURIComponent(String(params[name])) : whole,
	);
}

/** `path()` under the api prefix: an absolute URL path. */
export function url(id: RouteId, params: Record<string, string | number> = {}): string {
	return `${API_PREFIX}${path(id, params)}`;
}
